style:
canvas {
    height = 1000
    width = 1000
}

layout = [dots, rects, arrow]

debug {
    -- this is the color used for the debugging dots and lines
    color = rgba(0, 0, 0, 0.0)
}


forall Component c {
    c.center = (? in [dots, rects], ? in [dots, rects])

    -- c.dot is for debugging purposes and can be removed
    c.dot = Circle{
        center: c.center
        r: 5
        fillColor: debug.color
    }

    c.icon = Rectangle {
        center: c.center
        fillColor: rgba(1, 1, 1, 1)
        strokeColor: rgba(0, 0, 0, 1)
        strokeWidth: 2
        width: c.text.width + 30
        height: c.text.height + 30
    }

    c.text = Text {
        string: c.label
        center: c.center
    }

    layer c.dot above c.icon
    layer c.dot above c.text
}

forall Component a; Component b; Signal s
where s := mkSignal(a, b) {

    s.start_center = a.center
    s.end_center = b.center

    -- debug_line can be removed
    debug_line = Line {
        start: s.start_center
        end: s.end_center
        strokeStyle: "dashed"
        strokeColor: debug.color
    }
    layer debug_line below a.dot
    layer debug_line below b.dot

    ensure norm(s.start_center - s.end_center) < 50 in dots
}

-- mkSignal is not symmetric and hence the repetition here
forall Component a; Component b; Component c; Signal s1; Signal s2
where s1 := mkSignal(a, b); s2 := mkSignal(b, c) {
    encourage norm(a.center - c.center) == 10000 in [dots, rects]
}
forall Component a; Component b; Component c; Signal s1; Signal s2
where s1 := mkSignal(b, a); s2 := mkSignal(b, c) {
    encourage norm(a.center - c.center) == 10000 in [dots, rects]
}
forall Component a; Component b; Component c; Signal s1; Signal s2
where s1 := mkSignal(a, b); s2 := mkSignal(c, b) {
    encourage norm(a.center - c.center) == 10000 in [dots, rects]
}
forall Component a; Component b; Component c; Signal s1; Signal s2
where s1 := mkSignal(b, a); s2 := mkSignal(c, b) {
    encourage norm(a.center - c.center) == 10000 in [dots, rects]
}

forall Signal s1; Signal s2 {
    ensure shapeDistanceLines(s1.start_center, s1.end_center, s2.start_center, s2.end_center) > 0 in [dots]
}

forall Bus b {
    override b.icon.height = 400
    override b.icon.width = b.text.width + 40
}


forall Component a; Component b {
    ensure disjoint(a.icon, b.icon, 50) in rects
}

forall Component a; Component b; Signal s
where s := mkSignal(a, b) {
    ensure shapeDistance(a.icon, b.icon) < 60 in rects

    s.start = (? in [arrow], ? in [arrow])
    s.end = (? in [arrow], ? in [arrow])
    s.icon = Line {
        start: s.start
        end: s.end
        endArrowhead: "straight"
        strokeColor: #000000ff
    }
    ensure signedDistance(a.icon, s.start) == 5 in arrow
    ensure signedDistance(b.icon, s.end) == 5 in arrow
    strength = 100
    encourage strength * norm(s.end - s.start) == 0 in arrow

    s.near_center_start = encourage .5 * strength * norm(s.start - a.icon.center) == 0 in arrow
    s.near_center_end = encourage .5 * strength * norm(s.end - b.icon.center) == 0 in arrow
}

-- for arrows with the Bus, it does not point towards the center of the bus
forall Component a; Bus b; Signal s
where s := mkSignal(a, b) {
    delete s.near_center_end
}
forall Bus a; Component b; Signal s
where s := mkSignal(a, b) {
    delete s.near_center_start
}


-- split the apparent double-headed arrows into two arrows.
forall Component a; Component b; Signal s1; Signal s2
where s1 := mkSignal(a, b); s2 := mkSignal(b, a) {

    start = (s1.start + s2.end) / 2
    end = (s1.end + s2.start) / 2

    t = unit(end - start)
    n = rot90(t)
    h = 4

    override s1.icon = Line {
        start: start + h * n
        end: end + h * n
        endArrowhead: "straight"
        strokeColor: #000000ff
    }

    override s2.icon = Line {
        start: end - h * n
        end: start - h * n
        endArrowhead: "straight"
        strokeColor: #000000ff
    }
}

canvas {
   width = 510
   height = 382
}

global {
   shape background = Rectangle {
      center: (0,0)
      width: canvas.width
      height: canvas.height
      fillColor: #05c2
   }

   shape line1 = Text {
      string: "shape spline = Path {"
      fontFamily: "Menlo"
      fontSize: "9px"
      fillColor: #ffdd00
   }
   shape line2 = Text {
      center: line1.center + (122,-12)
      string: "d: interpolatingSpline( “closed”, [ p1, ..., pN ], tension )"
      fontFamily: line1.fontFamily
      fontSize: line1.fontSize
      fillColor: line1.fillColor
   }
   shape line3 = Text {
      center: line1.center + (-54,-24)
      string: "}"
      fontFamily: line1.fontFamily
      fontSize: line1.fontSize
      fillColor: line1.fillColor
   }
   shape code = Group {
      shapes: [ line1, line2, line3 ]
   }

   shape textBox = Rectangle {
      fillColor: #127c
   }
   encourage textBox.width == 0
   encourage textBox.height == 0
   ensure contains( textBox, code, 10 )

   layer code above textBox
   layer textBox above background
}

forall Point p {

   vec2 p.x = (?,?)

   shape p.icon = Circle {
      center: p.x
      r: 3
      fillColor: #fff
      strokeColor: #000
      strokeWidth: 1.5
   }

   layer global.textBox above p.icon
}

collect Point p into points {

   centers = listof x from points

   scalar tension = .25
   scalar baseWidth = 1
   scalar width = 1

   string closing = "closed"

   shape spline0 = Path {
      d: interpolatingSpline( closing, centers, 0*tension/3 )
      strokeColor: #1b8a1f33
      strokeWidth: baseWidth + 0*width/3
      strokeLinejoin: "round"
   }
   shape spline1 = Path {
      d: interpolatingSpline( closing, centers, 1*tension/3 )
      strokeColor: #1b8a1f99
      strokeWidth: baseWidth + 1*width/3
      strokeLinejoin: "round"
   }
   shape spline2 = Path {
      d: interpolatingSpline( closing, centers, 2*tension/3 )
      strokeColor: #1b8a1f99
      strokeWidth: baseWidth + 2*width/3
      strokeLinejoin: "round"
   }
   shape global.spline3 = Path {
      d: interpolatingSpline( closing, centers, 3*tension/3 )
      strokeColor: #1b8a1fff
      strokeWidth: baseWidth + 3*width/3
      strokeLinejoin: "round"
   }

   layer global.textBox above global.spline3
   layer global.spline3 above spline2
   layer spline2 above spline1
   layer spline1 above spline0
   layer spline0 above global.background
}

forall Point p {
   layer p.icon above global.spline3
}

canvas {
  width = 400
  height = 400
}

global {
  horAxis = Line {
    start: (-190, 0)
    end: (190, 0)
    endArrowhead: "straight"
    strokeColor: #aaaaaaff
  }

  verAxis = Line {
    start: (0, -190)
    end: (0, 190)
    endArrowhead: "straight"
    strokeColor: #aaaaaaff
  }

  xvec = 0
  yvec = 0

  N = 0
}

forall Point p
where p := MkPoint(x, y) {
  p.x = x
  p.y = y
  p.icon = Circle {
    r: 2
    center: (x * 25, y * 25)
    fillColor: #000000ff
  }

  layer p.icon above global.horAxis
  layer p.icon above global.verAxis
}

collect Number x into xs
where p := MkPoint(x, y)
with Point p {
  override global.xvec = xs
  override global.N = numberof xs
}

collect Number y into ys
where p := MkPoint(x, y)
with Point p {
  override global.yvec = ys
}

linearreg {
  beta = ?
  alpha = ?

  yhat = beta * global.xvec + repeat(global.N, alpha)

  yvec = global.yvec

  encourage minimal(1000 * vdistsq(yhat, yvec))

  startx = -7
  starty = alpha + beta * startx

  endx = 7
  endy = alpha + beta * endx

  regline = Line {
    start: (25 * startx, 25 * starty)
    end: (25 * endx, 25 * endy)
    ensureOnCanvas: false
    endArrowhead: "straight"
    strokeColor: #ff0000ff
  }
}

forall Point p {
  layer p.icon below linearreg.regline
}

canvas {
    width=1000
    height=1000
}

global {
    main = Circle {
        center: (0, 0)
        r: canvas.width / 5
        fillColor: #00000000 
        strokeWidth: 4
        strokeColor: #ffffffff
        style: "filter: blur(1px)"
    }
    line = Line {
        start: (-canvas.width / 2, 0)
        end: (canvas.width / 2, 0)
        style: "visibility: hidden"
    }
    hue = ?
}

forall Sphere s {
    s.center = (?, ?)
    s.r = ?
    s.icon = Circle {
        center: s.center
        r: s.r
        fillColor: hsva(global.hue + 2 * s.r, 100, 50, 0.05)
        ensureOnCanvas: false
    }
    s.icon2 = Circle {
        center: s.icon.center
        r: 0
        style: "visibility: hidden"
    }
    ensure touching(s.icon, global.line)
    ensure touching(s.icon2, global.main)
    global.main above s.icon
}

forall Sphere s 
where Display(s) {
    s.display = Circle {
        center: s.center
        r: s.r
        fillColor: hsva(global.hue + s.r, 100, 10, 0.5)
        ensureOnCanvas: false
    }
    s.displayCenter = Circle {
        center: s.center
        r: 6
        fillColor: #ffffffff
        ensureOnCanvas: false
    }
    s.displayCenter2 = Circle {
        center: (s.center[0], 0)
        r: 6
        fillColor: #ffffffff
        ensureOnCanvas: false
    }
    s.displayLine = Line {
        start: s.center
        end: (s.center[0], 0)
        strokeColor: #ffffffff
        strokeWidth: 4
        ensureOnCanvas: false
        style: "filter: blur(1px)"
    }
    s.displayCenter above s.display
    s.displayCenter2 above s.display
    s.displayLine below s.display
    global.main below s.display
    encourage s.r > 80
}

forall Sphere s; Sphere ds 
where Display(ds) {
    ds.displayCenter above s.icon
    ds.displayCenter2 above s.icon
    ds.displayLine above s.icon
}

forall Sphere s1; Sphere s2 
where Display(s1); Display(s2) {
    ensure disjoint(s1.icon, s2.icon)
}

canvas {
  width = 800
  height = 800
}

global {
  scalar alphaStep = 0.002
  scalar alphaMin = 0.1
  scalar coef = random(0.2, 0.5)
}

forall Pivot c {
  vec2 c.pos = (?, ?)
  scalar c.hue = ?

  shape c.icon = Circle {
    center: c.pos
    r: 3
    fillColor: hsva(c.hue, 50, 80, 1)
    strokeColor: #000
    strokeWidth: 2
  }
  shape c.iconb = Circle {
    center: c.pos
    r: 8
    fillColor: #ffffffff
    style: "filter: blur(3px)"
  }

  c.iconb below c.icon
}

collect Corner c into corners {
  positions = listof pos from corners
  ensure isEquilateral(positions, true)
  ensure isEquiangular(positions, true)
}

collect Corner c into corners 
foreach Center ce {
  positions = listof pos from corners
  ensure vdist(ce.pos, centerOfMass(positions)) == 0
}

collect Pivot c into pivots
where p := NextPoint(s)
foreach Point p; Point s {  
  positions = listof pos from pivots
  hues = listof hue from pivots
  scalar cornerIndex = randomIndex(0, count(hues))

  vec2 pivot = positions[cornerIndex]
  vec2 p.pos = global.coef * s.pos + (1 - global.coef) * pivot

  scalar p.alpha = max(global.alphaMin, s.alpha - global.alphaStep)

  scalar hue = hues[cornerIndex]
  scalar p.hue = 0.3 * s.hue + 0.7 * hue

  shape p.line = Line {
    start: s.pos
    end: p.pos
    strokeColor: hsva( p.hue, 50, 80, p.alpha )
    style: "filter: blur(1px)"
    ensureOnCanvas: false
  }
}

forall Point p; Point s; Pivot c
where p := NextPoint(s) {
  p.line below c.iconb
}  

forall Seed s {
  vec2 s.pos = (?, ?)
  scalar s.hue = ?
  scalar s.alpha = 0.5
}

forall Point p {
  shape p.blur = Circle {
    center: p.pos
    r: 4
    fillColor: hsva( p.hue, 50, 80, 1 )
    style: "filter: blur(2px)"
    ensureOnCanvas: false
  }
  shape p.icon = Circle {
    center: p.pos
    r: 3
    fillColor: #000
    ensureOnCanvas: false
  } 
}

forall Point p; Pivot c {
  p.blur below c.iconb
  p.icon below c.iconb
}

-- Settings

canvas {
  width = 600
  height = 600
}

global {
  scalar alphaScaling = 0.725
  scalar sizeScaling = 0.925
  scalar colorShift = 0.7
  scalar curveTension = .2

  shape background = Rectangle {
    fillColor: #000000ff
    center: (0, 0)
    width: canvas.width
    height: canvas.height
  }
}

-- Object Definitions

forall Transformation f {
  scalar sx = random(0.55, 0.65)
  scalar sy = random(0.55, 0.65)
  scalar theta = random(-2, 2)

  mat2x2 ms = scale2d(sx, sy)
  mat2x2 mr = rotate2d(theta)

  scalar ox = random(-100, 150)
  scalar oy = random(-100, 150)

  mat2x2 f.m = ms * mr
  mat2x2 f.offset = (ox, oy)

  scalar f.hue = ?
}

forall Seed s {
  vec2 s.pos = (0, 0)
  scalar s.hue = ?
  scalar s.size = 3.5
  scalar s.alpha = 0.3
}

-- Logic

forall Point p; Point s; Transformation f 
where p := NextPoint(s, f) {
  vec2 p.pos = f.m * s.pos + f.offset
  scalar p.hue = global.colorShift * s.hue + (1 - global.colorShift) * f.hue
  scalar p.size = global.sizeScaling * s.size
  scalar p.alpha = global.alphaScaling * s.alpha
}

collect Point p into ps
where OnCurve(p, c)
foreach Curve c {
  c.points = listof pos from ps
}

-- Display Shapes

forall Point p; Point s; Transformation f 
where p := NextPoint(s, f); DisplayTransformation(f) {
  shape p.line = Line {
    start: s.pos
    end: p.pos
    strokeColor: hsva( p.hue, 20, 100, p.alpha )
    strokeWidth: 1
    ensureOnCanvas: false
  }
  p.line above global.background
}

forall Point p
where DisplayPoint(p) {
  shape p.blur = Circle {
    center: p.pos
    r: p.size
    fillColor: hsva( p.hue, 60, 100, 0.4 )
    style: "filter: blur(2px)"
    ensureOnCanvas: false
  }
  shape p.icon = Circle {
    center: p.pos
    r: 1
    fillColor: hsva( p.hue, 60, 100, 1 )
    ensureOnCanvas: false
  }
  p.icon above p.blur
  p.blur above global.background
}

forall Curve c {
  shape curve = Path {
    d: interpolatingSpline( "open", c.points, global.curveTension )
    strokeColor: #ffffff1c
    strokeWidth: .3
    strokeLinejoin: "round"
    ensureOnCanvas: false
  }
  shape curve2 = Path {
    d: interpolatingSpline( "open", c.points, global.curveTension )
    strokeColor: #0bd0f31c
    strokeWidth: 1
    strokeLinejoin: "round"
    ensureOnCanvas: false
     style: "filter: blur(2px)"
  }
  curve above curve2
}

canvas {
  width = 400
  height = 400
}

layout = [dots, loops, arrows, text]

color {
  black = #000000
  white = #ffffff
}

num {
  radius = 5
  labelDist = 5
  edgeDist = 100
  repelDist = 1.5 * edgeDist
  offset = 10
  loopRadius = 15
  pointerX = 6
  pointerY = 4
}

forall Vertex v {
  v.dot = Circle {
    center: (? in dots, ? in dots)
    r: num.radius
    fillColor : color.black
  }

  v.text = Text {
    string: v.label
    fillColor: color.black
    fontFamily: "serif"
    fontSize: "18px"
    strokeColor: color.white
    strokeWidth: 4
    paintOrder: "stroke"
  }
  v.halfSize = (v.text.width / 2, v.text.height / 2)
  v.bottomLeft = v.text.center - v.halfSize
  v.topRight = v.text.center + v.halfSize

  v.text above v.dot

  encourage shapeDistance(v.dot, v.text) == num.labelDist in text
}

forall Vertex u; Vertex v {
  d = vdist(u.dot.center, v.dot.center)
  dHat = num.repelDist
  -- equation 6 from https://ipc-sim.github.io/
  encourage minimal(max(0, -sqr(d - dHat) * log(d / dHat))) in dots

  ensure disjoint(u.text, v.text, num.labelDist) in text
}

forall Vertex u; Vertex v; Link e where e := Arc(u, v) {
  a = u.dot.center
  b = v.dot.center
  t = normalize(b - a) -- tangent
  n = rot90(t) -- normal
  m = (a + b) / 2 -- midpoint

  e.start = a
  e.end = b
  e.theta = angleOf(t)
  e.offset = ? in dots
  e.arrow = Path {
    d: quadraticCurveFromPoints("open", [a, m + e.offset * n, b])
    strokeColor: color.black
  }

  e.step = ? in arrows
  e.pointerCenter = m + (e.offset / 2) * n + e.step * t
  p = e.pointerCenter
  x = num.pointerX
  y = num.pointerY
  e.pointer = Path {
    d: pathFromPoints("closed", [p - x * t + y * n, p + x * t, p - x * t - y * n])
    strokeColor: none()
    fillColor: color.black
  }

  e.arrow below u.dot
  e.arrow below v.dot
  e.pointer below e.arrow

  encourage vdist(u.dot.center, v.dot.center) < num.edgeDist in dots
  encourage minimal(sqr(e.offset)) in dots
  encourage minimal(sqr(e.step)) 
}

forall Vertex u; Vertex v; Link e1; Link e2 where e1 := Arc(u, v); e2 := Arc(u, v) {
  ensure abs(e2.offset - e1.offset) > 2 * num.offset in dots
}

forall Vertex u; Vertex v; Link e1; Link e2 where e1 := Arc(u, v); e2 := Arc(v, u) {
  ensure abs(e1.offset + e2.offset) > 2 * num.offset in dots
}

forall Vertex u; Vertex v; Link e where e := Arc(u, v); u has label {
  encourage maximal(min(num.labelDist, rectLineDist(u.bottomLeft, u.topRight, e.start, e.end))) in text
}

forall Vertex u; Vertex v; Link e where e := Arc(u, v); v has label {
  encourage maximal(min(num.labelDist, rectLineDist(v.bottomLeft, v.topRight, e.start, e.end))) in text
}

forall Vertex u; Vertex v; Vertex w; Link e where e := Arc(u, v); w has label {
  encourage maximal(min(num.labelDist, rectLineDist(w.bottomLeft, w.topRight, e.start, e.end))) in text
}

forall Vertex v; Link e where e := Arc(v, v) {
  e.theta = ? in loops
  n = (cos(e.theta), sin(e.theta)) -- normal
  delta = num.loopRadius * n

  e.arrow = Circle {
    center: v.dot.center + delta
    r: num.loopRadius
    strokeWidth: 1
    strokeColor: color.black
    fillColor: none()
  }

  t = rot90(n)
  p = v.dot.center + 2 * delta
  x = num.pointerX
  y = num.pointerY
  e.pointer = Path {
    d: pathFromPoints("closed", [p - x * t + y * n, p + x * t, p - x * t - y * n])
    strokeColor: none()
    fillColor: color.black
  }

  e.arrow below v.dot
  e.pointer below e.arrow
}

forall Vertex u; Vertex v; Link e1; Link e2 where e1 := Arc(u, v); e2 := Arc(v, v) {
  encourage maximal(cos(e2.theta - e1.theta)) in loops
}

forall Vertex u; Vertex v; Link e1; Link e2 where e1 := Arc(v, u); e2 := Arc(v, v) {
  encourage minimal(cos(e2.theta - e1.theta)) in loops
}

forall Link e1, e2
where e1 := Arc(a, b); e2 := Arc(c, d)
with Vertex a, b, c, d {
  ensure norm(e2.pointerCenter - e1.pointerCenter) > max(num.pointerX, num.pointerY)*3 in arrows
  encourage e1.step == e2.step
}

canvas {
  width = 600
  height = 600
}

layout = [dots, text, adjust]

color {
  black = #000000
  white = #ffffff
  blue = #0F2557
  lightblue = #28559A
}

num {
  radius = 5
  labelDist = 5
  edgeDist = 100
  repelDist = 1.5 * edgeDist
}

forall Vertex v {
  v.center = (?, ?)

  v.text = Text {
    center: v.center
    string: v.label
    fillColor: color.black
    fontFamily: "serif"
    fontSize: "18px"
    strokeColor: color.white
    strokeWidth: 4
    paintOrder: "stroke"
  }

  padding = 4
  v.dot = Circle {
    center: v.center
    r: padding + max(v.text.width, v.text.height) / 2
    fillColor : #0000
    strokeColor : color.black
    strokeWidth: 2
  }
  v.dot2 = Circle {
    center: v.center
    r: padding + max(v.text.width, v.text.height) / 2
    fillColor : #ffffffff
    strokeColor : #0000
  }
  v.text above v.dot2 
  v.dot above v.text

  encourage shapeDistance(v.dot, v.text) == num.labelDist except dots
}

forall Vertex u; Vertex v {
  d = vdist(u.dot.center, v.dot.center)
  dHat = num.repelDist
  -- equation 6 from https://ipc-sim.github.io/
  encourage minimal(max(0, -sqr(d - dHat) * log(d / dHat))) in dots

  ensure disjoint(u.text, v.text, num.labelDist) in text
}

forall Vertex u; Vertex v where Edge(u, v) as e {
  a = u.dot.center
  b = v.dot.center

  vec2 p1 = (?, ?)
  vec2 p2 = (?, ?)
  vec2 p3 = (?, ?)
  vec2 p4 = (?, ?)
  vec2 p5 = (?, ?)
  vec2 p6 = (?, ?)
  vec2 p7 = (?, ?)
  vec2 p8 = (?, ?)
  vec2 p9 = (?, ?)

  radius = 6
  shape e.c1 = Circle {
      center: p1
      r: radius
      fillColor: #0000
  }
  shape e.c2 = Circle {
      center: p2
      r: radius
      fillColor: #0000
  }
  shape e.c3 = Circle {
      center: p3
      r: radius
      fillColor: #0000
  }
  shape e.c4 = Circle {
      center: p4
      r: radius
      fillColor: #0000
  }
  shape e.c5 = Circle {
      center: p5
      r: radius
      fillColor: #0000
  }
  shape e.c6 = Circle {
      center: p6
      r: radius
      fillColor: #0000
  }
  shape e.c7 = Circle {
      center: p7
      r: radius
      fillColor: #0000
  }
  shape e.c8 = Circle {
      center: p8
      r: radius
      fillColor: #0000
  }
  shape e.c9 = Circle {
      center: p9
      r: radius
      fillColor: #0000
  }

  shape e.poly = Polyline {
    points: [a, p1, p2, p3, p4, p5, p6, p7, p8, p9, b]
    strokeWidth: 2
    strokeColor: #000
  }

  encourage minimal(elasticEnergy(e.poly.points, false))
  encourage isEquilateral(e.poly.points, false)

  e.start = a
  e.end = b
  e.arrow = Line {
    start: a
    end: b
    strokeColor: #0000
  }

  e.arrow below u.dot
