canvas {
    width = 100
    height = 100
}

global {
   color labelColor = #000
   string labelSize = "9px"
}

forall Point p {
    vec2 p.x = (?,?) -- location

    shape p.icon = Circle {
        center: p.x
        r: 1
        fillColor: #000
    }
}

forall Point p
where p has label {
   shape p.labelText = Equation {
      string: p.label
      center: p.x + 5*circleRandom()
      fillColor: global.labelColor
      fontSize: global.labelSize
   }
}

forall RandomWalk X {
    vec2 X.start = (?,?) -- start point
    mat2x2 A = .5*((1,0),(0,1)) -- covariance matrix
    vec2 omega = .2*circleRandom() -- drift
    X.curve = diffusionProcess(150, X.start, A, omega)

    shape X.icon = Path {
        d: interpolatingSpline("open", X.curve)
        strokeWidth: .5
        strokeColor: #1b1f8a66
        ensureOnCanvas: false
    }
}

forall RandomWalk X; Point p
where startsAt( X, p ) {
    override X.start = p.x
}

forall RandomWalk X; Point p
where endsAt( X, p ) {
    override p.x = lastPoint(X.curve)
}

forall Boundary B {

   vec2 B.x = (?,?)
   scalar theta = random(0,1) * MathPI()
   vec2 B.e1 = ( cos(theta), sin(theta) )
   vec2 B.e2 = (-sin(theta), cos(theta) )
   scalar w = 2*canvas.width
   scalar h = 2*canvas.width

   vec2 B.p0 = B.x - w*B.e1
   vec2 B.p1 = B.x + w*B.e1
   vec2 B.p2 = B.x + w*B.e1 - h*B.e2
   vec3 B.p3 = B.x - w*B.e1 - h*B.e2

   B.icon = Polygon{
      points: [ B.p0, B.p1, B.p2, B.p3 ]
      ensureOnCanvas: false
      fillColor: #0002
      ensureOnCanvas: false
   }
   B.boundary = Line {
      start: B.p0
      end: B.p1
      fillColor: none()
      strokeColor: #000
      strokeWidth: .5
      ensureOnCanvas: false
   }
}

forall Boundary B; Point a, b, c
where B := ReflectingBoundary( a, b, c ) {

   override B.x = b.x

   override B.e1 = unit(c.x - a.x)
   vec2 ab = b.x - a.x
   override B.e2 = unit(ab - dot(ab, B.e1)*B.e1)

   override B.boundary.strokeStyle = "dashed"
   override B.boundary.strokeDasharray = "2 2"
}

forall Boundary B; Point a, b, c
where a has label; B := ReflectingBoundary( a, b, c ) {
   override a.labelText.center = a.x - 6*B.e2
}
forall Boundary B; Point a, b, c
where b has label; B := ReflectingBoundary( a, b, c ) {
   override a.labelText.center = b.x + 6*B.e2
}
forall Boundary B; Point a, b, c
where c has label; B := ReflectingBoundary( a, b, c ) {
   override c.labelText.center = c.x - 6*B.e2
}

forall Boundary B; Point a, b
where B := AbsorbingBoundary( a, b ) {

   override B.x = b.x

   vec2 u1 = unit( b.x - a.x )
   vec2 u2 = ( -u1[1], u1[0] )

   override B.e1 = u2
   override B.e2 = u1

   scalar eps = norm( b.x - a.x )*1.1
   B.epsilonShell = Polygon {
      points: [ B.p0 - eps*B.e2, B.p1 - eps*B.e2, B.p1, B.p0 ]
      fillColor: #0003
      ensureOnCanvas: false
   }

   scalar markerOffset = 20
   scalar markerPadding = 2
   scalar markerCapWidth = 5
   vec2 m0 = B.x - markerPadding*B.e2 - markerOffset*B.e1
   vec2 m1 = B.x - (eps-markerPadding)*B.e2 - markerOffset*B.e1
   shape epsilonMarker = Line {
      start: m0
      end: m1
      strokeWidth: .5
      strokeColor: #888
   }
   shape epsilonMarkerStart = Line {
      start: m0 - markerCapWidth*B.e1/2
      end: m0 + markerCapWidth*B.e1/2
      strokeWidth: epsilonMarker.strokeWidth
      strokeColor: epsilonMarker.strokeColor
   }
   shape epsilonMarkerEnd = Line {
      start: m1 - markerCapWidth*B.e1/2
      end: m1 + markerCapWidth*B.e1/2
      strokeWidth: epsilonMarker.strokeWidth
      strokeColor: epsilonMarker.strokeColor
   }
   shape markerGroup = Group {
      shapes: [ epsilonMarker, epsilonMarkerStart, epsilonMarkerEnd ]
   }

   shape epsilonLabel = Equation {
      center: (m0+m1)/2 + 3*B.e1
      string: "\varepsilon"
      fillColor: epsilonMarker.strokeColor
      fontSize: global.labelSize
   }
}

forall Boundary B; Point a, b
where a has label; B := AbsorbingBoundary( a, b ) {
   override a.labelText.center = a.x - 6*B.e2
}
forall Boundary B; Point a, b
where b has label; B := AbsorbingBoundary( a, b ) {
   override b.labelText.center = b.x + 6*B.e2
}

forall Boundary B
where B has label {
   shape B.labelText = Equation {
      string: B.label
      center: B.x + 8*B.e2 + 20*B.e1
      fillColor: global.labelColor
      fontSize: global.labelSize
   }
}

-- Set the target diagram size
canvas {
   width = 240
   height = 180
}

-- A few colors used throughout
Colors {
   color black = rgba(0.,0.,0.,1.)
   color lightBlue = rgba( 27./255., 31./255., 138./255., .2 )
   color lightGreen = rgba( 27./255., 138./255., 31./255., .2 )
}

-- Define a global box around the canvas
Global {
   shape box = Rectangle {
      center: (0,0)
      width: canvas.width
      height: canvas.height
      strokeColor: rgba(0.,0.,0.,0.)
      fillColor: none()
      strokeWidth: 1
   }
}

-- Draw each word as text inside a
-- rounded rectangle.  Note that this
-- rule will get applied to all Words,
-- of any subtype.
forall Word w {

   -- Draw the text
   w.text = Text {
      center: (?,?) -- the center location will be optimized by Penrose
      string: w.label -- the label comes from the Substance program
      fillColor: Colors.black
      fontFamily: "Palatino"
      fontSize: "9px" -- make sure to use px, not pt, since pt appears inconsistently across programs/browsers
   }

   -- Draw the rectangle
   scalar padding = 8
   w.box = Rectangle {
      -- Use the same center, width, and
      -- height as the text, but add some padding
      center: w.text.center
      width: w.text.width + padding
      height: w.text.height + padding

      fillColor: Colors.lightGray
      strokeColor: Colors.black
      strokeWidth: .5
      cornerRadius: 5
   }

   -- Make sure the rectangle is always on the
   -- canvas (since the rectangle surrounds the text,
   -- the text will also then be on the canvas).
   ensure contains( Global.box, w.box )

   -- Draw the rectangle and text above the canvas (just in case
   -- the canvas is drawn using, e.g., an opaque fill color).
   layer w.box above Global.box
   layer w.text above Global.box
}

-- Set specific colors for specific types of text
forall AWord w {
   override w.box.fillColor = Colors.lightBlue
}
forall BWord w {
   override w.box.fillColor = Colors.lightGreen
}

-- Make sure no text boxes overlap
forall Word w1; Word w2 {
   ensure disjoint( w1.box, w2.box, 3. )
}

-- Encourage words of the same kind to be close to each-other
forall AWord w1; AWord w2 {
   encourage near( w1.box, w2.box )
}
forall BWord w1; BWord w2 {
   encourage near( w1.box, w2.box )
}

canvas {
    width = 1000
    height = 1000
}

general {
    startY = ?
    endY = ?

    startX = ?
    endX = ?
}

forall Party p
where p := MkParty(name) {
    p.iconTop = Circle {
        r : 50
        fillColor: #ffffffff
        strokeColor: #000000ff
        strokeWidth: 2
    }

    p.textTop = Text {
        string: name
        fontSize: "20px"
        center: p.iconTop.center
    }

    p.xCoord = p.iconTop.center[0]
    p.yCoord = p.iconTop.center[1]

    p.line = Line {
        start: (p.xCoord, p.iconTop.center[1])
        end: (p.xCoord, p.iconTop.center[1] - 800)
        endArrowhead: "straight"
        strokeStyle: "dashed"
        strokeWidth: 2
    }

    override general.startY = p.line.start[1] - 150
    override general.endY = p.line.end[1]

    p.icon = Group {
        shapes: [p.iconTop, p.textTop, p.line]
    }

    layer p.line below p.iconTop
}

collect Party party into parties {
    xs = listof xCoord from parties
    override general.startX = minList(xs)
    override general.endX = maxList(xs)
}

forall Party p1; Party p2 {
    ensure p1.yCoord == p2.yCoord
    ensure shapeDistanceRects(bboxPts(p1.icon), bboxPts(p2.icon)) > 0
}

forall Time t {
    t.lineYCoord = general.startY - (match_id - 1) * (general.startY - general.endY) / match_total

    t.topYCoord = t.lineYCoord + (general.startY - general.endY) / match_total
    t.bottomYCoord = t.lineYCoord

    t.line = Line {
        start: (general.startX - 50, t.lineYCoord)
        end: (general.endX, t.lineYCoord)
        strokeStyle: "dashed"
        strokeColor: #aaaaaaff
    }
    t.text = Equation {
        string: t.label
        center: (general.startX - 25, t.lineYCoord + 50)
        fontSize: "25px"
    }
}

forall Message m
where m := MkMessage(t, ff, tt, msg)
with Time t; Party ff; Party tt {
    m.yCoord = ?
    ensure m.yCoord > t.bottomYCoord + 30
    ensure m.yCoord < t.topYCoord - 30

    m.line = Line {
        start: (ff.xCoord, m.yCoord)
        end: (tt.xCoord, m.yCoord)
        endArrowhead: "straight"
        strokeWidth: 3
    }
    m.marker1 = Circle {
        center: (ff.xCoord, m.yCoord)
        r: 5
        fillColor: #00000055
    }
    m.marker2 = Circle {
        center: (tt.xCoord, m.yCoord)
        r: 5
        fillColor: #00000055
    }
    m.text = Text {
        string: msg
        fontSize: "15px"
        strokeColor: #ffffffff
        strokeWidth: 4
        paintOrder: "stroke"
    }

    ensure shapeDistanceRectLine(rectPts(m.text), m.line.start, m.line.end) == 5
    encourage 1000 * vdist(m.text.center, ((ff.xCoord + tt.xCoord) / 2, m.yCoord)) == 0
    ensure m.text.width < abs(tt.xCoord - ff.xCoord) - 70
}

forall Message m1; Message m2 {
    encourage notTooClose(m1.line, m2.line)
}

collect Message m into ms
where m := MkMessage(t, ff, tt, msg)
with Party ff; Party tt
foreach Time t;  {
    avgY = (t.topYCoord + t.bottomYCoord) / 2
    ensure average(listof yCoord from ms) == avgY
}

forall Message m; Party p {
    layer m.text above p.icon
}

canvas {
    width = 1000
    height = 1000
}

colors {
    black = #000000ff
    none = none()
    white = #ffffffff
    error = #ff0000ff
}

const {
    tableCenter = (0, 0)
    tableRadius = 300

    philRadius = 50
}

global {
    num_of_phil = 0 -- placeholder
    angle_between_phil = 2 * MathPI() / num_of_phil
    table = Circle {
        r: const.tableRadius
        center: const.tableCenter
        fillColor: colors.none
        strokeColor: colors.black
        strokeWidth: 2
    }
}

forall Phil p {
    p.angle = 12345 -- placeholder

    distFromCenter = const.tableRadius
    center = (distFromCenter * cos(p.angle), distFromCenter * sin(p.angle))
    p.icon = Circle {
        center: center
        r: const.philRadius
        strokeColor: colors.black
        strokeWidth: 2
        fillColor: colors.white
    }
    p.labelText = Text {
        string: p.label
        center: center
        strokeColor: colors.black
        fontSize: "24px"
        rotation: -toDegrees(p.angle) - 90
    }
    layer p.labelText above p.icon
}

forall Phil p where PhilFirst(p) {
    override p.angle = -MathPI() / 2
}

forall Phil p0, p1
where PhilNext(p0, p1) {
    override p1.angle = p0.angle + global.angle_between_phil
}

collect Phil p into ps {
    override global.num_of_phil = numberof ps
}

forall Fork f {
    f.angle = 12345 -- dummy value
    distFromCenter = 0.8 * const.tableRadius
    center = (distFromCenter * cos(f.angle), distFromCenter * sin(f.angle))
    f.comp1 = Text {
        center: center
        string: "∪"
        fontSize: "40px"
        rotation: -toDegrees(f.angle) - 90
    }
    f.comp2 = Text {
        center: center
        string: "|"
        fontSize: "40px"
        rotation: -toDegrees(f.angle) - 90
    }

    f.icon = Group {
        shapes: [f.comp1, f.comp2]
    }
}

forall Fork f; Phil p
where RightFork(p, f) {
    override f.angle = p.angle + global.angle_between_phil / 2
}

forall Fork f; Phil p
where Using(f, p) as u {
    u.errorText = Text {
        string: "Error: philosopher " + (nameof p) + " uses fork " + (nameof f) + " not adjacent to them"
        fontSize: "20px"
        fillColor: colors.error
    }
    override p.labelText.fillColor = colors.error
    override f.comp1.fillColor = colors.error
    override f.comp2.fillColor = colors.error
}

forall Fork f; Phil p
where Using(f, p) as u; RightFork(p, f) {
    delete u.errorText
    override p.labelText.fillColor = colors.black
    override f.comp1.fillColor = colors.black
    override f.comp2.fillColor = colors.black
    override f.angle = p.angle + atan(const.philRadius / const.tableRadius)
    layer f.icon below p.icon
}

forall Fork f; Phil p
where Using(f, p) as u; LeftFork(p, f) {
    delete u.errorText
    override p.labelText.fillColor = colors.black
    override f.comp1.fillColor = colors.black
    override f.comp2.fillColor = colors.black
    override f.angle = p.angle - atan(const.philRadius / const.tableRadius)
    layer f.icon below p.icon
}

forall Phil p1; Phil p2; Fork f
where Using(f, p1); Using(f, p2) {
    errorText = Text {
        string: "Error: fork " + (nameof f) + " is used by two philosophers " + (nameof p1) + " and " + (nameof p2)
        fontSize: "20px"
        fillColor: colors.error
    }
    override f.comp1.fillColor = colors.error
    override f.comp2.fillColor = colors.error
