layout = [shapes, arrows, inbox]

forall Node n {
    vec2 n.center = (? in shapes, ? in shapes)
    scalar n.normsq = normsq(n.center)
    shape n.icon = Circle {
        center: n.center
        r: 35
        fillColor: #ffffffff
        strokeColor: colors.contour
        strokeWidth: 2.6 - 0.008 * norm(n.center)
        ensureOnCanvas: false
    }
    shape n.text = Text {
        string: n.label
        strokeColor: #000000ff
        center: n.center
        fontSize: "20px"
    }
