      center: x.center
      string: x.label
      fontFamily: "Courier"
      fontSize: "20px"
      fontWeight: "bold"
      fillColor: Colors.black
   }

   x.bounds = Circle {
      center: x.center
      r: Global.setRadius
      fillColor: none()
   }
}

forall Set x; Set y {
   -- Try to make sure no labels overlap
   encourage notTooClose(x.bounds, y.bounds, 5.0)
}


forall Set x; Set y
where Subset(x, y) {

   vec2 p = x.center
   vec2 q = y.center
   vec2 u = unit(q-p)
   scalar r = Global.setRadius

   arrow = Line {
      start: p + r*u
      end: q - r*u
      strokeWidth : 4.0
      strokeColor : rgba(0.0, 0.0, 0.0, 1.0)
      endArrowhead: "straight"
      endArrowheadSize: .5
   }

   -- Position y above x
   encourage above(y.bounds, x.bounds)

   -- Have sets 'fight' to be aligned with the superset's x-position
   encourage x.bounds.center[0] == y.bounds.center[0]
}

